# Reproduce participant-free aggregate panels in the public GitHub preparation.
suppressPackageStartupMessages({library(data.table);library(ggplot2);library(svglite);library(ragg)})
dir.create('aggregate_figures',showWarnings=FALSE);LWD<-1.5/72*25.4
saveplot<-function(p,n){ggsave(file.path('aggregate_figures',paste0(n,'.pdf')),p,device=cairo_pdf,width=150,height=110,units='mm');ggsave(file.path('aggregate_figures',paste0(n,'.svg')),p,device=svglite,width=150,height=110,units='mm');ggsave(file.path('aggregate_figures',paste0(n,'.tiff')),p,device=agg_tiff,width=150,height=110,units='mm',dpi=600)}
for(s in c('EXON','GENE','INTRON','TSS200')){con<-gzfile(file.path('aggregate',paste0(s,'_pooled_feature_statistics.tsv.gz')),'rt');txt<-readLines(con,warn=FALSE);close(con);d<-fread(text=paste(txt,collapse='\n'));d[,direction:=ifelse(FDR<.05,ifelse(beta>0,'Higher','Lower'),'Other')];p<-ggplot(d,aes(beta,-log10(pmax(P,.Machine$double.xmin)),colour=direction))+geom_point(size=.6,alpha=.7)+geom_hline(yintercept=-log10(.05),linetype=2,linewidth=LWD)+scale_colour_manual(values=c(Higher='#D55E00',Lower='#0072B2',Other='#B8B8B8'))+labs(x='Adjusted log2 signal difference',y='−log10(P)',title=s)+theme_classic(base_family='Arial',base_size=12);saveplot(p,paste0(s,'_volcano'))}
d<-fread('aggregate/Model_performance.tsv')[task%in%c('source','pathology')&region%in%c('EXON','GENE','INTRON','TSS200')];p<-ggplot(d,aes(AUC,region,colour=task))+geom_errorbar(aes(xmin=CI_low,xmax=CI_high),orientation='y',position=position_dodge(width=.5),linewidth=LWD)+geom_point(position=position_dodge(width=.5))+geom_vline(xintercept=.5,linetype=2)+labs(x='Internal AUC (conditional 95% CI)',y=NULL)+theme_classic(base_family='Arial',base_size=12);saveplot(p,'Internal_performance')
cat('PASS public aggregate figures; no individual inputs were needed\n')
